        "category": "Penjaga Nalar",
        "bio_paragraphs": [
            "Di tengah stigma bahwa filsafat adalah ilmu rumit yang menyesatkan atau elitis, Dr. Fahruddin Faiz mengambil jalan yang sangat unik dan teduh: membawa diskursus filsafat barat dan timur ke dalam serambi masjid. Sejak 2013, ia mengampu forum mingguan Ngaji Filsafat di Masjid Jendral Sudirman Yogyakarta secara gratis, terbuka, dan inklusif bagi siapa saja.",
            "Dengan gaya tutur berbahasa Jawa-Indonesia yang tenang, penuh analogi keseharian, dan diselingi senyum santun, Fahruddin Faiz membedah pemikiran para filsuf besar—dari Socrates, Al-Ghazali, Rumi, Marcus Aurelius, hingga Jean-Paul Sartre. Rekaman kajiannya yang disebarluaskan secara sukarela di platform digital telah didengar oleh jutaan generasi muda yang sedang mengalami krisis eksistensial, kecemasan mental, dan kejenuhan atas kepalsuan media sosial.",
            "Bagi anak muda di era disrupsi, Fahruddin Faiz adalah oase intelektual dan spiritual: mengajarkan bahwa berpikir kritis tidak harus diiringi kesombongan, dan kebijaksanaan hidup selalu berakar pada kerendahan hati untuk terus belajar menata diri sendiri."
        ],
        "quote": "Filsafat bukan untuk membuatmu merasa lebih tinggi atau lebih pintar dari orang lain, melainkan instrumen agar batinmu lebih jernih, bijaksana, dan tidak mudah menghakimi sesama.",
