        "title": "Peneliti Kebijakan Publik, Koordinator Penasihat KSP (2015–2019) & Co-founder Nalar Institute",
        "category": "Penjaga Nalar",
        "bio_paragraphs": [
            "Menggabungkan kecermatan akademis global dengan pengalaman membedah labirin birokrasi istana, Yanuar Nugroho adalah salah satu pemikir kebijakan publik paling berpengaruh di Indonesia. Meraih gelar Ph.D dari University of Manchester dan berkarier sebagai peneliti inovasi sosial, Yanuar terpanggil pulang untuk mengabdi sebagai Deputi II Kantor Staf Presiden (KSP) 2015–2019.",
            "Di dalam birokrasi, Yanuar berjuang keras menanamkan tradisi Evidence-Based Policy—memastikan bahwa setiap keputusan pembangunan negara, mulai dari dana desa hingga bantuan sosial, dirancang berdasarkan riset saintifik dan data lapangan yang solid, bukan sekadar kompromi politisi transaksional. Melalui Nalar Institute dan Centre for Innovation Policy and Governance (CIPG), ia terus membina ekosistem think tank independen di tanah air.",
            "Bagi generasi muda yang ingin membawa perubahan struktural, Yanuar adalah teladan teknokrat berintegritas: membuktikan bahwa kritik terhadap negara harus disertai penguasaan data yang presisi dan arsitektur solusi yang dapat dieksekusi secara nyata."
        ],
        "quote": "Kebijakan publik yang tidak berlandaskan data empiris dan sains adalah bentuk kezaliman teknokratis yang mempertaruhkan nasib jutaan rakyat miskin.",
        "photo_url": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=800&q=80",
        "verified": true,
        "status_text": "VERIFIKASI TERKURASI",
