        "category": "Penjaga Nalar",
        "bio_paragraphs": [
            "Mengawali pendidikan di jurusan Desain Produk ITB sebelum meraih gelar doktor dalam bidang Science and Technology Studies (STS) dari Rensselaer Polytechnic Institute New York, Prof. Sulfikar Amir adalah salah satu intelektual diaspora Indonesia paling vokal di panggung dunia. Kini menjabat sebagai Associate Professor di NTU Singapura, kepakarannya berfokus pada sosiologi kebencanaan dan risiko infrastruktur.",
            "Kala pandemi COVID-19 dan proyek-proyek mercusuar infrastruktur pemerintah menuai polemik, Sulfikar tak segan menyuntikkan kritik ilmiah berbasis data simulasi ke linimasa publik. Ia konsisten mengingatkan para pembuat kebijakan tentang bahaya Institutional Vulnerability—kerapuhan tata kota dan tata kelola keselamatan yang kerap dikorbankan demi percepatan politik.",
            "Bagi generasi muda, Sulfikar memperlihatkan model ilmuwan sejati: independen, berani menantang narasi populis penguasa dengan ketelitian metodologis, dan mendedikasikan sains demi keselamatan hidup warga."
        ],
