            "content_full": "Mbah Sadiman tidak pernah mengenal istilah jargon climate change atau carbon offset. Ia hanya melihat tetangganya kehausan dan sawah desa pecah-pecah kekeringan. Dengan cangkul di pundak dan kantong berisi bibit beringin, ia membuktikan bahwa cinta seorang manusia pada buminya mampu membalikkan takdir kepunahan air.",
