        "name": "Silverius Oscar Unggul",
        "title": "Presiden Perkumpulan Telapak & Pelopor Community Logging Lestari (FSC)",
        "category": "Penyelamat Bumi",
        "bio_paragraphs": [
            "Di era 1990-an saat pembalakan liar (illegal logging) merajalela di Sulawesi Tenggara dan Kalimantan didukung oleh oknum bersenjata dan sindikat kayu transnasional, Silverius Oscar Unggul (akrab disapa Onte) bertaruh nyawa. Bersama Perkumpulan Telapak dan EIA, ia menyusup ke dalam hutan merekam aksi kejahatan kehutanan dan membawanya ke forum internasional.",
            "Namun Onte menyadari satu kenyataan pahit di lapangan: warga lokal ikut menebang pohon karena mereka lapar dan tidak punya pilihan ekonomi. Maka ia mengubah paradigma perlawanan dengan mendirikan Koperasi Kehutanan Koperasi Wana Lestari Menawa (KHJM) di Konawe Selatan—koperasi masyarakat pertama di dunia yang berhasil meraih sertifikasi kelestarian hutan internasional (FSC).",
            "Onte membuktikan bahwa hutan adat bisa dikelola secara lestari (community logging) dengan nilai ekspor tinggi tanpa harus membabat habis pohon. Model ini dinobatkan sebagai salah satu solusi kehutanan terbaik dunia oleh Skoll Foundation dan Schwab Foundation."
        ],
        "quote": "Menyelamatkan hutan tidak bisa dilakukan dengan memusuhi masyarakat di sekitarnya; jadikan warga pemilik sah dari industri kayu lestari, maka mereka sendiri yang akan menjadi benteng pertahanan rimba.",
        "photo_url": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=800&q=80",
        "verified": true,
        "status_text": "VERIFIKASI TERKURASI",
        "social_links": {
            "instagram": "https://instagram.com/silverius_oscar_unggul",
            "website": "https://telapak.org"
        },
        "theme_default": "light"
