        "name": "David Christian",
        "title": "Co-founder Evoware & Rethink (Pelopor Material Kemasan Sirkular Rumput Laut)",
        "category": "Penyelamat Bumi",
        "bio_paragraphs": [
            "Melihat gunungan sampah saset dan pembungkus makanan plastik yang mencemari sungai-sungai kota Jakarta sepulang menyelesaikan studi di Selandia Baru, David Christian merasa terpanggil untuk menciptakan alternatif material kemasan yang benar-benar ramah lingkungan dari akar sumber daya lokal Indonesia.",
            "Pada 2015, David mendirikan Evoware—sebuah startup bioteknologi material sirkular yang mengembangkan kemasan alternatif sekali pakai berbahan dasar rumput laut (seaweed-based edible packaging). Kemasan ciptaannya tidak hanya dapat larut dalam air hangat dan terurai 100% menjadi pupuk alami dalam hitungan minggu, tetapi juga aman dikonsumsi manusia.",
            "Melalui inovasi Evoware dan kampanye Rethink Plastic, David menghubungkan pemecahan darurat sampah hilir dengan peningkatan kesejahteraan ribuan keluarga petani rumput laut tradisional di pesisir Indonesia Timur, membuktikan keunggulan inovasi climate-tech anak bangsa di panggung dunia."
        ],
        "quote": "Solusi terbaik dari masalah sampah plastik kemasan hilir sebenarnya sudah disediakan oleh alam nusantara di hulu: rumput laut yang dapat terurai alami dan aman dikonsumsi.",
