            "tag": "INTERNET RAKYAT",
            "read_time": "8 Menit Membaca",
            "description": "Catatan rekayasa Onno W. Purbo tentang bagaimana peralatan dapur sederhana mampu meruntuhkan monopoli operator telekomunikasi.",
            "content_full": "Ketika operator besar menolak menarik kabel fiber optik ke desa karena dianggap tidak menguntungkan secara bisnis, warga tidak boleh pasrah hidup dalam kegelapan informasi. Wajanbolic adalah simbol kemandirian: bahwa dengan nalar rekayasa, rakyat mampu membangun jalannya sendiri menuju peradaban dunia.",
