            "tag": "ETIKA SAINS",
            "read_time": "7 Menit Membaca",
            "description": "Pentingnya membebaskan ilmu pengetahuan dari belenggu paten komersial demi lompatan kecerdasan bersama anak bangsa.",
            "content_full": "Ilmu yang dikunci di balik dinding berbayar hanya akan melahirkan ketimpangan sosial. Kedaulatan digital bangsa ini tidak akan pernah tercapai jika generasi mudanya hanya menjadi konsumen pasif teknologi asing tanpa pernah mengerti baris kode di dalamnya.",
