        "name": "Mama Aleta Baun",
        "title": "Tokoh Adat Suku Mollo NTT, Goldman Environmental Prize Winner & Penjaga Pegunungan Mutis",
        "category": "Pejuang Akar Rumput",
        "bio_paragraphs": [
            "Di pedalaman Pegunungan Mutis, Timor Tengah Selatan, Nusa Tenggara Timur, Mama Aleta Baun memimpin perlawanan damai yang mengguncang korporasi tambang marmer dan pemegang konsesi perusak lingkungan. Menghadapi ancaman pembunuhan, penyerangan fisik, hingga terpaksa bersembunyi di dalam hutan bersama bayinya, Mama Aleta menolak menyerah.",
            "Menyadari bahwa marmer yang hendak dikeruk perusahaan adalah batu sakral penahan mata air bagi tiga suku besar (Mollo, Miomafo, Amanatun), Mama Aleta memobilisasi ratusan perempuan adat untuk menggelar aksi duduk menenun kain tradisional di mulut tambang selama setahun penuh. Aksi tanpa kekerasan ini melumpuhkan total alat-alat berat perusahaan hingga tambang ditutup secara permanen.",
            "Dianugerahi Goldman Environmental Prize 2013, Mama Aleta membuktikan kekuatan kearifan lokal perempuan adat: mengubah tenun pewarna alami menjadi senjata perlawanan menjaga keabadian mata air nusantara."
        ],
        "quote": "Batu adalah tulang kita, air adalah darah kita, tanah adalah daging kita, dan hutan adalah rambut kita. Menyerahkan tanah ulayat kepada tambang marmer sama saja dengan memutilasi tubuh kita sendiri.",
