            "title": "Menyemen Kaki Demi Air: Mengapa Pegunungan Karst Kendeng Adalah Nafas Hidup Petani Jawa",
            "tag": "HAK AGRARIA",
            "read_time": "8 Menit Membaca",
            "description": "Catatan perjuangan para Kartini Kendeng menyuarakan jeritan tanah air yang hendak ditambang pabrik semen.",
            "content_full": "Semen tidak bisa dimakan saat paceklik tiba. Ketika gua-gua karst dan sungai bawah tanah di Kendeng diledakkan dinamit, mata air akan mati dan ribuan hektare sawah akan berubah menjadi gurun pasir. Petani berdiri menjaga Kendeng bukan untuk diri mereka sendiri, melainkan agar seluruh rakyat Indonesia tetap bisa makan nasi.",
