        "title": "Pendiri & CEO Rumah Mocaf Indonesia (Inovator Rantai Nilai Tepung Singkong Banjarnegara)",
        "category": "Arsitek Usaha Mandiri",
        "bio_paragraphs": [
            "Sepulang menempuh studi sarjana dan magister di bidang Teknik Elektro, Riza Azyumarridha Azra merasa teriris hatinya saat kembali ke tanah kelahirannya di Banjarnegara, Jawa Tengah, dan melihat para petani singkong menangis karena harga jual singkong anjlok hingga Rp 200 per kilogram saat panen raya—jauh di bawah biaya tanam.",
            "Riza menolak membiarkan para petani terlilit utang tengkulak. Pada 2014, ia mendirikan Rumah Mocaf Indonesia. Riza memperkenalkan teknologi fermentasi enzimatik organik untuk mengolah singkong segar menjadi Modified Cassava Flour (Mocaf)—tepung serbaguna bebas gluten (gluten-free) berkualitas tinggi yang mampu menggantikan tepung terigu gandum impor.",
            "Melalui model koperasi terintegrasi, Rumah Mocaf kini membina ribuan petani dan ibu-ibu pengolah singkong di puluhan desa di Banjarnegara, menyerap ribuan ton singkong dengan harga beli yang adil, serta mengekspor tepung Mocaf dan produk turunannya (mi dan kukis bebas gluten) ke Inggris, Dubai, dan Turki."
        ],
        "quote": "Singkong bukan makanan orang miskin yang tertinggal; dengan fermentasi enzimatik modern, singkong lokal adalah tepung bebas gluten masa depan yang membebaskan bangsa ini dari jeratan impor gandum.",
        "photo_url": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=800&q=80",
