        "title": "Co-founder Foodizz (Akademi Edukasi Bisnis Kuliner) & Serial Culinary Entrepreneur",
        "category": "Arsitek Usaha Mandiri",
        "bio_paragraphs": [
            "Setelah sukses merintis dan membesarkan berbagai jenama kuliner lokal ternama di Bandung dan Jakarta—mulai dari Warunk Upnormal, Bakso Boedjangan, hingga Sambal Khas Karmila—Stefanie Kurniadi menyaksikan fakta menyedihkan di lapangan: lebih dari 80% pengusaha kuliner pemula di Indonesia gulung tikar dalam tahun pertama karena minimnya literasi sains bisnis terapan.",
            "Pada 2018, Stefanie bersama rekan-rekannya mendirikan Foodizz (The 1st F&B EduTech in Indonesia). Melalui Foodizz, Stefanie mengkodifikasi belasan tahun pengalaman jatuh-bangun membangun ratusan gerai kuliner ke dalam kurikulum pembelajaran digital yang terstruktur, mudah dipahami, dan dapat dieksekusi langsung oleh pelaku UMKM makanan-minuman.",
            "Melalui kelas-kelas inkubasi, podcast edukasi, dan buku panduan bisnis kuliner, Stefanie telah membimbing lebih dari 500.000 pengusaha kuliner di seluruh Indonesia agar mampu membangun bisnis makanan yang berumur panjang, taat pajak, dan mampu membuka jutaan lapangan kerja mandiri."
        ],
        "quote": "Membangun bisnis kuliner bukan sekadar urusan resep masakan yang enak; ia adalah sains manajemen rantai pasok, kepatuhan finansial, standardisasi SOP, dan ketahanan membaca psikologi konsumen.",
