        "title": "Pendiri Asgar Muda Foundation & Pelopor Kewirausahaan Sosial Pemuda Garut",
        "category": "Arsitek Usaha Mandiri",
        "bio_paragraphs": [
            "Setelah menyelesaikan pendidikan di Teknik Sipil ITB dan meraih berbagai tawaran karier korporasi multinasional, Goris Mustaqim memilih pulang ke kampung halamannya di Garut, Jawa Barat. Ia resah melihat tingginya angka pengangguran pemuda desa dan fenomena urbanisasi liar yang memicu kerentanan sosial.",
            "Pada 2007, Goris mendirikan Asgar Muda Foundation (Asal Garut Muda)—sebuah inkubator kewirausahaan sosial pemuda pertama di tingkat kabupaten. Goris memetakan komoditas unggulan lokal Garut—mulai dari sentra kerajinan kulit Sukaregang, perkebunan minyak akar wangi (vetiver) kelas dunia, hingga agribisnis jeruk dan domba Garut—dan melatih ribuan pemuda desa menjadi wirausahawan mandiri.",
            "Diakui sebagai Young Global Leader oleh World Economic Forum (WEF) di Davos dan menerima penghargaan dari Presiden RI, Goris membuktikan bahwa desentralisasi ekonomi kreatif perdesaan adalah kunci pemerataan kemakmuran bangsa."
        ],
        "quote": "Pemuda daerah tidak perlu berbondong-bondong merantau ke Jakarta untuk mencari sesuap nasi; gali potensi unggulan tanah kelahiranmu dan jadilah tuan di tanah sendiri.",
        "photo_url": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=800&q=80",
        "verified": true,
        "status_text": "VERIFIKASI TERKURASI",
