        "category": "Perawat Jiwa & Rasa",
        "bio_paragraphs": [
            "Sebagai vokalis, gitaris, dan penulis lirik utama di balik grup musik independen Efek Rumah Kaca (ERK) dan Pandai Besi, Cholil Mahmud adalah salah satu komposer paling berpengaruh yang merekam luka politik, kegelisahan sosial, dan kerapuhan moral bangsa Indonesia ke dalam karya musik yang kontemplatif dan abadi.",
            "Karya-karyanya—seperti 'Di Udara' (lagu perlawanan mengenang pembunuhan aktivis HAM Munir), 'Hilang', 'Cinta Melulu', 'Desember', hingga album epik 'Rimpang'—menjadi lagu wajib bagi gerakan masyarakat sipil, demonstrasi mahasiswa, dan refleksi batin jutaan anak muda. Cholil menolak kompromi integritas terhadap sensor korporasi dan memilih jalur kemandirian ekosistem musik independen.",
            "Bagi generasi muda, Cholil Mahmud membuktikan bahwa musik bukan sekadar komoditas hiburan pelarian sesaat, melainkan senjata puitis untuk merawat ingatan kolektif bangsa, menyembuhkan luka batin, dan menolak tunduk pada impunitas kekuasaan."
        ],
        "quote": "Pasar dan panggung komersial bisa diciptakan dan direkayasa oleh industri, tapi kejujuran nurani dalam bermusik dan berpihak pada korban ketidakadilan tak akan pernah bisa diperjualbelikan.",
