        "category": "Perawat Jiwa & Rasa",
        "bio_paragraphs": [
            "Lahir di Bone, Sulawesi Selatan, M. Aan Mansyur adalah salah satu penyair kontemporer paling cemerlang di Indonesia yang berhasil membuktikan bahwa puisi sastra bermutu tinggi mampu merebut hati generasi digital tanpa kehilangan ketajaman maknanya.",
            "Karya-karya puisinya—seperti 'Tidak Ada New York Hari Ini' (yang menjadi jiwa dalam film Ada Apa Dengan Cinta? 2), 'Melihat Api Bekerja', 'Sebelum Sendiri', hingga 'Mengapa Luka Tidak Memaafkan Pisau'—dikenal memiliki metafora sunyi yang sangat menghunjam batin pembaca. Tak hanya menulis di atas kertas, Aan membangun ruang literasi mandiri Katakerja di Makassar—sebuah perpustakaan komunitas dan ruang dialog inklusif bagi pemuda Indonesia Timur.",
            "Bagi generasi muda yang haus akan ketenangan batin, Aan Mansyur adalah perawat sunyi: mengingatkan kita bahwa membaca puisi adalah cara paling lembut untuk merawat empati kemanusiaan di dunia yang kian bising dan individualistik."
        ],
        "quote": "Puisi adalah ruang hening untuk menyapa diri sendiri di tengah riuhnya linimasa yang kerap membuat kita lupa arah jalan pulang.",
