        "title": "Penulis, Kreator Naratif & Pendiri Ekosistem Cerita NKCTHI (Nanti Kita Cerita Tentang Hari Ini)",
        "category": "Perawat Jiwa & Rasa",
        "bio_paragraphs": [
            "Mengawali langkah lewat buku ilustrasi nostalgia masa kecil 'Generasi 90an' yang sukses besar, Marchella Febritrisia Putri (Marchella FP) melakukan lompatan artistik yang mengubah lanskap penerbitan buku modern Indonesia saat merilis 'Nanti Kita Cerita Tentang Hari Ini' (NKCTHI) pada 2018.",
            "Dengan kejelian merajut kutipan-kutipan pendek yang sarat perenungan emosional, ilustrasi minimalis yang elegan, dan pemahaman mendalam atas luka keluarga serta kecemasan anak muda, NKCTHI menjelma menjadi fenomena literatur nasional yang terjual ratusan ribu eksemplar dan diadaptasi menjadi film box office peraih jutaan penonton.",
            "Marchella terus melahirkan karya-karya narasi pemulihan batin seperti 'Kamu Terlalu Banyak Bercanda' (KTBB) dan 'Tabi'. Ia adalah arsitek pencerita visual yang merawat kesehatan emosional generasi muda: membimbing pembaca untuk berani berdamai dengan trauma keluarga dan menemukan rasa syukur di tengah ketidaksempurnaan hidup."
        ],
        "quote": "Buku adalah pelukan hangat bagi jiwa-jiwa yang merasa sendirian di tengah kota besar; sebaris kalimat sederhana yang jujur dapat menyelamatkan seseorang yang sedang putus asa.",
        "photo_url": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=800&q=80",
        "verified": true,
        "status_text": "VERIFIKASI TERKURASI",
