            "title": "Merangkul Emosi yang Terlarang: Mengapa Menangis dan Merasa Hampa Adalah Hak Manusiawi",
            "tag": "SENI & KESEHATAN BATIN",
            "read_time": "7 Menit Membaca",
            "description": "Refleksi Lala Bohang tentang bahaya toxic positivity yang memaksa manusia untuk selalu terlihat bahagia dan produktif.",
            "content_full": "Masyarakat modern kerap memandang kesedihan dan rasa cemas sebagai penyakit yang harus segera disingkirkan. Padahal, emosi gelap tersebut adalah bagian alami dari diri kita yang ingin didengarkan. Memberi ruang bagi kesedihan adalah cara kita merawat keutuhan jiwa.",
