        "name": "Pandji Pragiwaksono",
        "title": "Pelopor Stand-Up Comedy Indonesia, Pendiri Comika Corp & Komika Satir Politik",
        "category": "Penjaga Tawa",
        "bio_paragraphs": [
            "Mengawali karier sebagai penyiar radio dan presenter televisi, Pandji Pragiwaksono mengambil peran historis sebagai pionir yang membidani kelahiran industri Stand-Up Comedy modern di Indonesia sejak 2011. Lulusan Desain Produk ITB ini melihat komedi tunggal sebagai senjata intelektual untuk mendidik warga membicarakan isu tabu secara rasional.",
            "Melalui tur komedi tunggal keliling dunianya—seperti Mesakke Bangsaku, Juru Bicara, Pragiwaksono, hingga Komoidoi—Pandji berani membedah isu hak asasi manusia, kebrutalan sensor penyiaran, politik identitas pemilu, hingga kritik terhadap institusi kepolisian dan kepresidenan. Ia kemudian mendirikan Comika Corp—ekosistem industri komedi mandiri yang memfasilitasi ratusan komika daerah memiliki kedaulatan karya melalui platform digital sendiri.",
            "Kini menembus panggung legendaris Comedy Cellar di New York City, Pandji membuktikan bahwa komedi berbasis nalar kritis anak bangsa mampu berdiri sejajar di pusat peradaban komedi dunia."
        ],
        "quote": "Komedi tunggal bukan sekadar pelawak yang melempar lelucon receh; ia adalah seni menguji nalar publik, membongkar kemunafikan penguasa, dan menertawakan ketakutan terbesar bangsa.",
