        "title": "Komika Satir Perdesaan, Aktor Sinema & Penggerak Guyub Tani Kebumen",
        "category": "Penjaga Tawa",
        "bio_paragraphs": [
            "Lahir dan besar di pelosok pedesaan Kebumen, Jawa Tengah, Sadana Agung Sulistya membawa keaslian dialek ngapak dan atmosfer sawah perdesaan yang sangat kental ke atas panggung Stand Up Comedy Indonesia (SUCI 6). Berbeda dengan materi komika perkotaan yang serba glamor, Sadana justru membongkar keabsurdan relasi kuasa antara petani gurem, aparat desa, dan tengkulak gabah dengan humor satir yang amat cerdas.",
            "Gaya komedinya memadukan keluguan khas wong ndeso dengan ketajaman observasi sosiologis. Sadana menunjukkan bahwa tawa orang desa bukanlah lelucon slapstick yang bodoh, melainkan strategi kultural untuk merawat kewarasan batin saat harga panen anjlok dan biaya hidup kian mencekik.",
            "Melalui perannya di berbagai film layar lebar sinema independen dan konten digital komedi sawah, Sadana konsisten menjaga martabat identitas perdesaan nusantara: membuktikan bahwa kejujuran bertutur dari tanah kelahiran adalah pesona artistik yang tak lekang oleh waktu."
        ],
        "quote": "Guyon wong ndeso itu bukan buat merendahkan diri, tapi cara paling anggun menertawakan getirnya hidup bertani di tengah gempuran harga pupuk dan tengkulak.",
