        "title": "Jurnalis Investigatif, Pewawancara Kritis Kekuasaan, Pendiri Narasi & Duta Baca Indonesia",
        "category": "Pencerah Generasi",
        "bio_paragraphs": [
            "Karier Najwa Shihab tidak dibangun dari kenyamanan meja redaksi ber-AC, melainkan dari keberaniannya turun ke lapangan meliput bencana tsunami Aceh 2004 hingga mencecar para pejabat tinggi di kursi panas Mata Najwa. Alumnus Fakultas Hukum UI ini membuktikan bahwa wawancara jurnalistik yang tajam dapat menjadi panggung pengadilan publik ketika sistem hukum formal kerap ragu menghadapi kekuasaan.",
            "Ketika iklim pertelevisian nasional kian terjebak pada komersialisasi rating dangkal dan konglomerasi politik, Najwa mengambil langkah independen dengan mendirikan Narasi pada 2018. Ia membangun ekosistem jurnalisme partisipatif dan newsroom berbasis investigasi data (OSINT) yang menjadikan anak muda bukan sekadar penonton, melainkan agen pengawal demokrasi dan akuntabilitas kebijakan publik.",
            "Sebagai Duta Baca Indonesia selama bertahun-tahun, Najwa terus menjelajahi pelosok nusantara menyalakan lentera literasi: membuktikan bahwa membaca dan berpikir kritis adalah syarat mutlak bagi lahirnya warga negara yang merdeka dan bermartabat."
        ],
        "quote": "Kekuasaan cenderung korup, dan satu-satunya obat penawar dari penyakit itu adalah warga yang berani mengawasi, bertanya, dan menagih janji tanpa rasa takut.",
