        "name": "Angga Fauzan",
        "title": "Co-founder & CEO MySkill (Inovator Upskilling Karier & Demokratisasi Skill Digital Inklusif)",
        "category": "Pencerah Generasi",
        "bio_paragraphs": [
            "Tumbuh besar dari keluarga bersahaja di Boyolali, Jawa Tengah, di mana keluarganya sempat terpaksa tinggal di bekas kandang kambing setelah rumahnya digusur, Angga Fauzan membuktikan bahwa keterbatasan ekonomi ekstrem bukanlah akhir dari cita-cita seorang anak desa.",
            "Melalui beasiswa Bidikmisi, Angga menyelesaikan studi Desain Komunikasi Visual di ITB dan melanjutkan magister di University of Edinburgh, Skotlandia, melalui beasiswa LPDP. Menyadari tingginya angka pengangguran lulusan perguruan tinggi akibat kesenjangan antara kurikulum kampus dan kebutuhan industri digital modern, pada 2021 Angga mendirikan MySkill.",
            "MySkill berkembang pesat menjadi platform upskilling karier terbesar di Indonesia yang telah melatih lebih dari 1,5 juta generasi muda dalam bidang data science, digital marketing, UI/UX, dan software development dengan biaya terjangkau. Masuk dalam daftar Forbes 30 Under 30 Asia, Angga adalah bukti nyata bahwa talenta dari pelosok desa mampu memimpin revolusi pendidikan vokasi digital nasional."
        ],
        "quote": "Akses pendidikan vokasi dan keterampilan karier kelas dunia harus bisa diraih oleh anak desa manapun tanpa terhalang sekat biaya mahal dan jarak geografis.",
