            "title": "Darah, Keringat, dan Filosofi Silat: Perjalanan Iko Uwais Merevolusi Sinema Aksi Dunia",
            "tag": "SINEMA & BUDAYA",
            "read_time": "8 Menit Membaca",
            "description": "Kisah perjuangan Iko dari latihan fisik keras di sanggar kayu hingga memimpin koreografi laga bersama aktor-aktor papan atas dunia.",
            "content_full": "Di luar negeri, mereka kagum bukan cuma karena kecepatan pukulan kami, tapi karena di dalam silat ada ritme dan rasa. Setiap gerakan pukulan dan tangkisan selalu diimbangi dengan sikap hormat. Silat adalah pertahanan diri yang menjunjung tinggi kemanusiaan lawan.",
            "link_url": "/artikel/iko-uwais-1",
