            "profile_id": "gen-iko-uwais",
            "title": "Membangun Industri Stunt Profesional: Visi Uwais Team untuk Masa Depan Aktor Laga Lokal",
            "tag": "INDUSTRI KREATIF",
            "read_time": "6 Menit Membaca",
            "description": "Bagaimana Uwais Team menerapkan standar keselamatan tinggi dan regenerasi atlet silat menjadi stunt performer profesional.",
            "content_full": "Aksi laga yang keren adalah aksi yang aman. Kami tidak ingin talenta muda mengorbankan cedera fatal demi sebuah adegan. Disiplin, perhitungan matematis jarak, dan saling percaya adalah fondasi dari setiap koreografi laga kelas dunia.",
