        "title": "Ilmuwan Genetika Tanaman Global, Direktur Riset Orion Genomics & Pemeta Genom Kelapa Sawit",
        "category": "Duta Talenta",
        "bio_paragraphs": [
            "Muhammad Arief Budiman adalah sosok ilmuwan biologi molekuler dan genetika tanaman kelas dunia asal Yogyakarta yang kiprahnya menjadi rujukan riset agrikultur internasional. Menyelesaikan pendidikan sarjana di Institut Pertanian Bogor (IPB) dan meraih gelar doktor dalam bidang genetika tanaman dari Texas A&M University, Arief telah memimpin berbagai proyek pemetaan genomik tanaman strategis dunia.",
            "Sebagai Direktur Riset dan Operasi Laboratorium di Orion Genomics, St. Louis, Amerika Serikat, Arief memimpin terobosan monumental dalam pemetaan genom kelapa sawit (*Elaeis guineensis*). Penemuannya atas penanda genetik *Shell gene* memungkinkan perkebunan menyeleksi bibit sawit unggul sejak fase kecambah, melipatgandakan produktivitas minyak per hektare hingga 30% tanpa perlu memperluas pembukaan lahan hutan baru.",
            "Karyanya yang dipublikasikan di jurnal sains paling bergengsi dunia, Nature, menjadi sumbangsih nyata sains Indonesia bagi solusi krisis pangan dan keberlanjutan lingkungan hidup global."
        ],
        "quote": "Beras dan pangan yang kita makan setiap hari adalah hasil dari kode genetik alam yang luar biasa rumit. Memetakan DNA tanaman bukan untuk merusak alam, melainkan untuk memastikan bumi tetap mampu memberi makan peradaban tanpa membabat habis hutan rimba.",
        "photo_url": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=800&q=80",
