            "title": "Dari Jakarta ke Gurun Coachella: Kejujuran Lirik NIKI Memikat Telinga Dunia",
            "tag": "SENI MUSIK",
            "read_time": "7 Menit Membaca",
            "description": "Catatan perjalanan emosional NIKI menulis lagu-lagu personal yang merangkum kerapuhan dan kekuatan perempuan muda.",
            "content_full": "Waktu menulis di kamar tidur dengan gitar tua, saya tidak pernah membayangkan ribuan orang di New York, London, dan Paris akan ikut menyanyikan lirik tentang SMA di Jakarta. Musik punya sihir aneh: semakin spesifik dan jujur cerita pribadimu, semakin universal resonansinya di hati pendengar.",
