            "title": "Menaklukkan Tradisi Akademik Jepang: Perjalanan Prof. Ken Soetanto Meraih 4 Gelar Doktor",
            "tag": "PENDIDIKAN & KETANGGUHAN",
            "read_time": "8 Menit Membaca",
            "description": "Kisah inspiratif tentang bagaimana anak kampung dari Surabaya menjadi guru besar legendaris di universitas paling bergengsi di Tokyo.",
            "content_full": "Ketika saya pertama kali tiba di Tokyo tanpa bisa berbahasa Jepang, banyak orang meremehkan. Namun saya berprinsip: jika orang lain belajar 5 jam, saya harus belajar 10 jam. Otak manusia itu elastis; yang membedakan keberhasilan adalah seberapa besar rasa lapar jiwamu untuk menyerap ilmu pengetahuan.",
