        "title": "Diplomat Kuliner Tradisional Nusantara, Pakar Gastronomi Legendaris & Penulis Cita Rasa Indonesia",
        "category": "Duta Talenta",
        "bio_paragraphs": [
            "William Wirjaatmadja Wongso (dikenal luas sebagai William Wongso) adalah raksasa gastronomi nusantara yang mendedikasikan lebih dari lima dekade hidupnya untuk mendokumentasikan, membela, dan mempromosikan keaslian kuliner tradisional Indonesia ke panggung diplomasi internasional. Pria kelahiran Malang ini menjelajahi ribuan desa, pasar tradisional, dan dapur tetua adat dari Sabang sampai Merauke demi meneliti profil rasa bumbu otentik nusantara.",
            "Keahliannya diakui secara global oleh para juru masak elit dunia. Ia adalah anggota kehormatan *Chaîne des Rôtisseurs*, penerima penghargaan tertinggi diplomasi kuliner dari pemerintah Prancis (*Chevalier dans l’Ordre National du Mérite*), dan tokoh kunci yang memandu chef legendaris Gordon Ramsay dalam mendalami seni memasak rendang asli di pedalaman Tanah Datar, Sumatra Barat untuk tayangan *National Geographic*.",
            "Mahakaryanya, buku *Flavors of Indonesia: William Wongso's Culinary Wonders*, memenangkan penghargaan paling bergengsi dunia *Gourmand World Cookbook Awards* sebagai Buku Masakan Terbaik Dunia (Best Cookbook of the Year), mengukuhkan rempah nusantara sebagai mahakarya gastronomi peradaban manusia."
        ],
        "quote": "Rendang bukan sekadar masakan daging berbumbu kelapa. Di dalamnya ada kosmologi kesabaran mengaduk kuali selama delapan jam, kearifan rempah rimba tropis, dan harga diri kebudayaan bangsa yang tak ternilai harganya.",
