            "title": "Di Balik Tirai Algoritma: Bagaimana Media Sosial Merancang Kemarahan Publik Demi Profit",
            "tag": "KRITIK MEDIA",
            "read_time": "8 Menit Membaca",
            "description": "Pembedahan teori ekonomi perhatian (attention economy) dan mengapa kabar buruk selalu lebih cepat viral dibanding kabar baik.",
            "content_full": "Algoritma tidak peduli apakah sebuah informasi itu benar atau berbahaya bagi kohesi bangsa. Yang diukur oleh sistem adalah tingkat keterlibatan (engagement). Dan emosi manusia yang paling mudah memicu komentar dan share adalah kemarahan dan ketakutan. Menyadari jebakan ini adalah langkah pertama merebut kembali kemerdekaan berpikir kita.",
