        "category": "Panggung Ekspresi",
        "bio_paragraphs": [
            "Jovial da Lopez dan Andovi da Lopez adalah duo bersaudara revolusioner dalam jagat hiburan digital Indonesia lewat kanal SkinnyIndonesian24. Mengawali karier pembuatan konten komedi sejak 2011 saat masih menempuh studi di Universitas Indonesia (Jovial di Fisika MIPA dan Andovi di Hukum UI), mereka menetapkan standar artistik dan integritas moral yang sangat tinggi di tengah maraknya konten instan.",
            "Karya-karya mereka adalah mahakarya seni pertunjukan digital yang memadukan kritik politik tajam dengan teater musikal megah. Mulai dari serial video legendaris 'Epic Rap Battles of Presidents' yang mengedukasi sejarah kepemimpinan bangsa, hingga 'DPR Musikal'—sebuah pertunjukan musikal satir orisinil berdurasi panjang yang membongkar intrik legislasi dan korupsi politik dengan standar produksi teater Broadway.",
            "Keputusan mereka untuk menutup kanal SkinnyIndonesian24 tepat di usia 10 tahun pada 2021 membuktikan integritas tanpa tanding: bahwa bagi mereka, berkarya adalah persembahan pengabdian bangsa, bukan sekadar perburuan algoritma monetisasi seumur hidup."
        ],
        "quote": "Bila anak muda tidak peduli pada politik, masa depan negeri ini akan terus ditentukan oleh orang-orang yang tidak peduli pada nasib mereka. Kita membungkus kritik dengan seni musikal agar pesan itu bergaung di dada generasi penerus.",
        "photo_url": "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=800&q=80",
        "verified": true,
        "status_text": "VERIFIKASI TERKURASI",
