            "Leonardo Edwin adalah representasi generasi muda Indonesia yang berwawasan global namun mencintai akar budaya tanah airnya dengan sepenuh jiwa. Lahir dan besar di Batam, Kepulauan Riau, Leo menempuh pendidikan sarjana di University of Washington, Seattle, Amerika Serikat di bidang Sistem Informasi dan Manajemen Sumber Daya Alam.",
            "Lewat kanalnya, Leo mendokumentasikan perjuangan hidup sebagai mahasiswa rantau mandiri di Amerika, ketekunannya mendaki puncak-puncak gunung salju di Cascade Range, serta kecintaannya memperkenalkan bahasa dan makanan Indonesia kepada mahasiswa internasional. Karyanya menginspirasi jutaan pelajar di tanah air tentang kedisiplinan belajar, etika kerja paruh waktu, dan pentingnya adaptasi budaya.",
